#pragma once

// Entry checks of gui_forms::TreeListView, generated by tools/ic_declarations.py from
// include/gui_forms/controls/tree_list_view.ic.toml; edit the declaration, not this file. Each predicate is one
// `requires` clause of the declaration, so the condition the header states and the check the code runs are one text
// (docs/ic_declarations.md in template_harness).

#include "gui_forms/controls/tree_list_view.hpp"

namespace gui_forms::detail::ic::tree_list_view {

// TreeListView::indentation: finite(incoming) and incoming >= indentation_least and incoming <= indentation_most; else
// failure invalid_argument.
[[nodiscard]] constexpr bool admits_indentation(const double incoming) noexcept {
    const bool result = __builtin_isfinite(incoming)
                     && (incoming >= TreeListView::minimum_indentation)
                     && (incoming <= TreeListView::maximum_indentation);
    return result;
}

} // namespace gui_forms::detail::ic::tree_list_view
